import { usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from '@/composables/useI18n';
import en from '@/routes/en';
import fr from '@/routes/fr';
import type { LocaleCode, SitePageName } from '@/types';

const localizedRoutes = { fr, en } satisfies Record<LocaleCode, unknown>;

type QueryParameters = Record<string, string>;

/**
 * Localized page URLs, generated by Wayfinder from the Laravel routes.
 */
export function useSiteRoutes() {
    const page = usePage();
    const { locale } = useI18n();

    const routes = computed(() => localizedRoutes[locale.value]);
    const currentPath = computed(() => page.url.split(/[?#]/)[0]);

    function pageUrl(name: SitePageName, query?: QueryParameters): string {
        return routes.value[name].url(query ? { query } : undefined);
    }

    function quoteUrl(query?: QueryParameters): string {
        return `${pageUrl('contact', query)}#devis`;
    }

    function isCurrent(name: SitePageName): boolean {
        return currentPath.value === pageUrl(name);
    }

    /** The current page in another language, falling back to that language's home page. */
    function localizedPath(target: LocaleCode): string {
        const paths = (page.props.seo as { paths?: Record<LocaleCode, string> })
            ?.paths;

        return paths?.[target] ?? localizedRoutes[target].home.url();
    }

    const inquiryStoreRoute = computed(() => routes.value.inquiries.store());

    return {
        pageUrl,
        quoteUrl,
        isCurrent,
        localizedPath,
        inquiryStoreRoute,
    };
}
